<?php declare(strict_types=1);use FMonitor2\YiiRuntime\Assets\AssetVersion;use FMonitor2\YiiRuntime\ViewSupport;use yii\helpers\Html;$id=$calculation['calculationId'];$rev=$calculation['revision'];$draft=$calculation['status']==='draft';$accepted=$calculation['status']==='accepted';$activePaymentId=$calculation['activePaymentId']??null;$recoveryPost=is_array($recovery['post']??null)?$recovery['post']:[];$recoveryError=(string)($recovery['error']??'');$employeeGroups=[];foreach($calculation['recipients']as$r)$employeeGroups[$r['employeeId']][]=$r;ViewSupport::begin($this,'Расчёт #'.$id,$identity,'otiz','wide');$this->registerJsFile('/pilot/assets/'.AssetVersion::file('otiz.js'),['type'=>'module','position'=>\yii\web\View::POS_END]);?>
<main class="fm2-otiz fm2-otiz-page"><section class="fm2-otiz-surface"><div class="fm2-otiz-tabs-surface"><?=$this->render('_otiz-nav',['current'=>'snapshot'])?></div></section><header class="fm2-page-header"><div><h1>Расчёт #<?=$id?></h1><p><?=Html::encode($calculation['reportDate'])?> · revision <?=$rev?></p></div><a class="shlz-button shlz-button--secondary" href="/pilot/otiz/calculations/<?=$id?>/export.xlsx?mode=<?=$draft?'draft':'history'?>">Скачать Excel</a></header><?php if($recoveryError!==''):?><p class="shlz-alert shlz-alert--danger" role="alert"><?=Html::encode($recoveryError)?></p><?php endif?><?php if(isset($query['paid'])):?><p role="status">Выплата отмечена</p><?php endif?>
